-- GENERATED by `python3 analytics/build.py render` from analytics/dbt/models/marts/fact_encounter.sql. Do not edit.
-- Fact encounter. Grain: one row per encounter (visit) of every source, from gold_encounter_summary, so the admission
-- and readmission rules are the Gold ones. Keys to dim_patient (the person), dim_date (admit and discharge day),
-- dim_practitioner (the attending) and dim_location (the last place). The emergency flag is true for an emergency
-- department visit, and for a hospital admission that came in as an emergency (Encounter.priority EM from HL7 v2 PV1-4,
-- or the MIMIC admission type EMER, which MIMIC sends as the class).
-- is_live_feed marks the visits of the live Riverside General feed (gold_live_encounter), the base of the census.
CREATE OR REPLACE TABLE fact_encounter AS
SELECT
    MD5((SELECT pseudonym_salt FROM governance_settings) || '|' || COALESCE(CAST(e.encounter_id AS VARCHAR), ''))                                                 AS encounter_sk,
    k.patient_sk,
    k.patient_record_sk,
    CAST(EXTRACT(YEAR FROM CAST(e.start_at AS DATE)) * 10000 + EXTRACT(MONTH FROM CAST(e.start_at AS DATE)) * 100 + EXTRACT(DAY FROM CAST(e.start_at AS DATE)) AS INTEGER)                                           AS admit_date_key,
    CAST(EXTRACT(YEAR FROM CAST(e.end_at AS DATE)) * 10000 + EXTRACT(MONTH FROM CAST(e.end_at AS DATE)) * 100 + EXTRACT(DAY FROM CAST(e.end_at AS DATE)) AS INTEGER)                                             AS discharge_date_key,
    CASE WHEN e.attending_practitioner_id IS NULL THEN 'unknown'
         ELSE MD5(COALESCE(CAST(e.attending_practitioner_id AS VARCHAR), '')) END                   AS attending_practitioner_sk,
    CASE WHEN e.last_location_id IS NULL THEN 'unknown'
         ELSE MD5(COALESCE(CAST(e.last_location_id AS VARCHAR), '')) END                            AS last_location_sk,
    e.source,
    e.class_code,
    e.encounter_kind,
    e.status,
    e.is_admission,
    CASE WHEN e.encounter_kind = 'emergency visit' THEN TRUE
         WHEN e.is_admission AND (s.priority_code = 'EM' OR (e.source = 'mimic' AND e.class_code = 'EMER')) THEN TRUE
         ELSE FALSE END                                                                  AS is_emergency,
    CASE WHEN l.encounter_id IS NOT NULL THEN TRUE ELSE FALSE END                        AS is_live_feed,
    e.start_at                                                                           AS admit_at,
    e.end_at                                                                             AS discharge_at,
    CASE WHEN e.end_at IS NOT NULL
         THEN ROUND(DATEDIFF('minute', e.start_at, e.end_at) / 60.0, 2) END              AS length_of_stay_hours,
    e.length_of_stay_days,
    e.readmitted_30d,
    CAST(e.bed_moves AS INTEGER)                                                         AS bed_moves
FROM gold_encounter_summary e
JOIN silver_encounter s            ON s.encounter_id = e.encounter_id
LEFT JOIN int_patient_key k        ON k.patient_id = e.patient_id
LEFT JOIN gold_live_encounter l    ON l.encounter_id = e.encounter_id;
